export const getAuthJwtLoginUrl = () => {
  return `/api/v1/auth/jwt/login`
}

/**
 * @summary Auth:Jwt.Login
 */
export const authJwtLogin = async (
  bodyAuthJwtLogin: BodyAuthJwtLogin,
  options?: Parameters<typeof fetcher>[1]
): Promise<BearerResponse> => {
  const formUrlEncoded = new URLSearchParams()
  if (
    bodyAuthJwtLogin.client_id !== undefined &&
    bodyAuthJwtLogin.client_id !== null
  ) {
    formUrlEncoded.append(`client_id`, bodyAuthJwtLogin.client_id)
  }
  if (
    bodyAuthJwtLogin.client_secret !== undefined &&
    bodyAuthJwtLogin.client_secret !== null
  ) {
    formUrlEncoded.append(`client_secret`, bodyAuthJwtLogin.client_secret)
  }
  if (
    bodyAuthJwtLogin.grant_type !== undefined &&
    bodyAuthJwtLogin.grant_type !== null
  ) {
    formUrlEncoded.append(`grant_type`, bodyAuthJwtLogin.grant_type)
  }
  formUrlEncoded.append(`password`, bodyAuthJwtLogin.password)
  if (bodyAuthJwtLogin.scope !== undefined) {
    formUrlEncoded.append(`scope`, bodyAuthJwtLogin.scope)
  }
  formUrlEncoded.append(`username`, bodyAuthJwtLogin.username)

  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>
  ): Record<string, string | readonly string[]> => {
    if (!h) return {}
    if (h instanceof Headers) return Object.fromEntries(h.entries())
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string]
        )
      )
    }
    const headers: Record<string, string | readonly string[]> = {}
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value
    }
    return headers
  }
  return fetcher<BearerResponse>(getAuthJwtLoginUrl(), {
    ...options,
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
      ...getHeaders(options?.headers),
    },
    body: formUrlEncoded,
  })
}

